class Solution {
public:
    int subsetXORSum(vector<int>& nums) {
        int totalOr = 0;
        for (int x : nums) totalOr |= x;
        return totalOr << (nums.size() - 1);
    }
};

class Solution {
    public int subsetXORSum(int[] nums) {
        int totalOr = 0;
        for (int x : nums) totalOr |= x;
        return totalOr << (nums.length - 1);
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var subsetXORSum = function(nums) {
    let totalOr = 0;
    for (const x of nums) totalOr |= x;
    return totalOr << (nums.length - 1);
};
